import pandas as pd

def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = None

    # Step 1: filter events strictly after watermark
    if high_ts is not None:
        cdc = cdc[cdc["event_ts"] > high_ts]
    else:
        cdc = cdc.iloc[0:0]

    # Step 2: per product_id, pick latest event by (event_ts, event_seq)
    if len(cdc) > 0:
        cdc_sorted = cdc.sort_values(
            by=["product_id", "event_ts", "event_seq"],
            ascending=[True, True, True]
        )
        latest = cdc_sorted.groupby("product_id", as_index=False).tail(1)
    else:
        latest = cdc.iloc[0:0]

    # Build dict of target snapshot by product_id for easy update
    target = target.set_index("product_id", drop=False)

    result_rows = {}
    for _, row in target.iterrows():
        result_rows[row["product_id"]] = {
            "product_id": row["product_id"],
            "name": row["name"],
            "price": row["price"],
            "last_event_ts": row["last_event_ts"],
        }

    for _, ev in latest.iterrows():
        pid = ev["product_id"]
        op = ev["op"]
        if op == "D":
            if pid in result_rows:
                del result_rows[pid]
        else:  # 'I' or 'U'
            result_rows[pid] = {
                "product_id": pid,
                "name": ev["name"],
                "price": ev["price"],
                "last_event_ts": ev["event_ts"],
            }

    if len(result_rows) > 0:
        new_snapshot = pd.DataFrame(list(result_rows.values()))
    else:
        new_snapshot = pd.DataFrame(columns=["product_id", "name", "price", "last_event_ts"])

    # Ensure proper dtypes
    new_snapshot["product_id"] = new_snapshot["product_id"].astype("int64")
    new_snapshot["price"] = new_snapshot["price"].astype("float64")
    new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"])

    new_snapshot = new_snapshot.sort_values("product_id").reset_index(drop=True)

    return {"new_snapshot": new_snapshot}
